"""Compose policy and journal data into a plan.

This module owns graph validation and execution order, applies replay against
the persisted journal, enforces the budget and assembles the result.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, caps_budget, limit_for


def failure(code):
    """The exact failure envelope from SPEC.md (no partial actions)."""
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(ordered_ids, units_by_id):
    """Build the exact success envelope; ``units`` sums the emitted actions."""
    return {
        "status": "ok",
        "actions": list(ordered_ids),
        "units": sum(units_by_id[change_id] for change_id in ordered_ids),
    }


def check_dependencies(changes):
    """Fail on missing dependency targets and on cycles.

    Missing targets are reported as ``unknown-dependency`` and take precedence
    over cycles, matching the order of the SPEC bullets.
    """
    known = {change["id"] for change in changes}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
    topological_order(changes)


def topological_order(changes):
    """Return the full deterministic topological order of every change.

    Among currently eligible changes (all dependencies already placed) the
    lexicographically smallest ID is emitted first, so the order is unique for
    a given change set. Cycles raise ``dependency-cycle``.
    """
    indegree = {change["id"]: 0 for change in changes}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        # ``depends_on`` is already deduplicated, so each edge counts once.
        for dependency in change["depends_on"]:
            indegree[change["id"]] += 1
            dependents[dependency].append(change["id"])
    eligible = [change_id for change_id, degree in indegree.items() if degree == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        current = heapq.heappop(eligible)
        order.append(current)
        for dependent in dependents[current]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(eligible, dependent)
    if len(order) != len(indegree):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    """Turn one validated request into the exact SPEC result object."""
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        units_by_id = {change["id"]: change["units"] for change in changes}
        applied = read_applied(request.get("applied"), set(units_by_id))
        check_dependencies(changes)
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    applied_set = set(applied)
    if request["action"] == "plan":
        # Already applied entries satisfy dependencies and cost no budget.
        emitted = [change_id for change_id in order if change_id not in applied_set]
    else:
        # Undo the applied changes in the reverse of the full order.
        emitted = [change_id for change_id in reversed(order) if change_id in applied_set]

    if caps_budget(request["action"]):
        units = sum(units_by_id[change_id] for change_id in emitted)
        if units > budget:
            return failure("budget-exceeded")
    return success(emitted, units_by_id)

