from journal import JournalError, normalize
from policy import PolicyError, check_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def order(changes):
    """Return the full deterministic topological order of change IDs.

    Kahn's algorithm; among currently eligible nodes the smallest ID wins,
    so the same request always yields the same order. Being a *full* order
    matters to rollback, which reverses it.
    """
    by_id = {change["id"]: change for change in changes}
    pending = {cid: len(change["depends_on"]) for cid, change in by_id.items()}
    dependents = {cid: [] for cid in by_id}
    for change in changes:
        for target in change["depends_on"]:
            dependents[target].append(change["id"])
    ready = [cid for cid, count in pending.items() if count == 0]
    heapq.heapify(ready)
    ordered = []
    while ready:
        cid = heapq.heappop(ready)
        ordered.append(cid)
        for successor in dependents[cid]:
            pending[successor] -= 1
            if pending[successor] == 0:
                heapq.heappush(ready, successor)
    if len(ordered) != len(by_id):
        # Leftover nodes are exactly those on or behind a cycle.
        raise PolicyError("dependency-cycle")
    return ordered


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        state = normalize(request)
        action = request["action"]
        by_id = {change["id"]: change for change in state["changes"]}
        ordered = order(state["changes"])
        if action == "plan":
            # Applied entries need no replay ordering decision: they already
            # satisfy dependencies and their units were spent before, so only
            # new units are charged against the budget.
            actions = [cid for cid in ordered if cid not in state["applied"]]
        else:
            actions = [cid for cid in reversed(ordered) if cid in state["applied"]]
        units = sum(by_id[cid]["units"] for cid in actions)
        check_budget(units, budget, action)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

