"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, normalize, read_retain
from policy import PolicyError, check_budget, effective_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def order(changes):
    """Return the full deterministic topological order of change IDs.

    Kahn's algorithm; among currently eligible nodes the smallest ID wins,
    so the same request always yields the same order. Being a *full* order
    matters to rollback, which reverses it.
    """
    by_id = {change["id"]: change for change in changes}
    pending = {cid: len(change["depends_on"]) for cid, change in by_id.items()}
    dependents = {cid: [] for cid in by_id}
    for change in changes:
        for target in change["depends_on"]:
            dependents[target].append(change["id"])
    ready = [cid for cid, count in pending.items() if count == 0]
    heapq.heapify(ready)
    ordered = []
    while ready:
        cid = heapq.heappop(ready)
        ordered.append(cid)
        for successor in dependents[cid]:
            pending[successor] -= 1
            if pending[successor] == 0:
                heapq.heappush(ready, successor)
    if len(ordered) != len(by_id):
        # Leftover nodes are exactly those on or behind a cycle.
        raise PolicyError("dependency-cycle")
    return ordered


def retained_closure(retain, by_id, applied):
    """Return retained IDs plus their applied transitive dependencies.

    G2 rollback: a kept change is only coherent if the applied changes it
    depends on (transitively) are kept too, so walk `depends_on` from each
    retained ID without visiting a node twice -- a diamond dependency stays
    finite and shared dependencies are collected once. Unapplied dependencies
    break the walk: they were never released, so there is nothing to keep and
    retaining them would invent an action outside the journal.
    """
    keep = set()
    stack = list(retain)
    while stack:
        cid = stack.pop()
        if cid in keep:
            continue
        keep.add(cid)
        for target in by_id[cid]["depends_on"]:
            if target in applied and target not in keep:
                stack.append(target)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Order matters twice here. `limit_for` runs before `normalize` because
        # G2 freezes production even when the graph is malformed -- such a
        # request must never reach a journal error. `normalize` still runs
        # before any budget comparison because units are counted post-replay.
        budget = effective_budget(limit_for(request), request["action"])
        state = normalize(request)
        action = request["action"]
        by_id = {change["id"]: change for change in state["changes"]}
        ordered = order(state["changes"])
        if action == "plan":
            # Applied entries need no replay ordering decision: they already
            # satisfy dependencies and their units were spent before, so only
            # new units are charged against the budget.
            actions = [cid for cid in ordered if cid not in state["applied"]]
        else:
            # Rollback-only `retain` (malformed or unapplied here is
            # invalid-retain) is expanded to its applied dependency closure;
            # both stay out of the reverse-order emit below, which otherwise
            # keeps the original deterministic sequence.
            keep = retained_closure(
                read_retain(request.get("retain"), state["applied"]),
                by_id,
                state["applied"],
            )
            actions = [cid for cid in reversed(ordered)
                       if cid in state["applied"] and cid not in keep]
        units = sum(by_id[cid]["units"] for cid in actions)
        check_budget(units, budget, action)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

