    """Return deduplicated changes as dicts with an id/component/units/depends_on set.

    Identical duplicate records collapse into one before accounting or graph
    construction. Equality covers id, component, units and the set of
    dependencies. Two records sharing an ID without being equal are a
    conflicting-change.
    """
    if not isinstance(records, list):
        _invalid("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            _invalid("invalid-change")
        depends_on = _read_dependency_ids(row.get("depends_on", []))
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": depends_on,
        }
        previous = seen.get(change["id"])
        if previous is None:
            seen[change["id"]] = change
            changes.append(change)
        elif not _identical(previous, change):
            _invalid("conflicting-change")
    return changes


def _identical(left, right):
    return (left["id"] == right["id"] and left["component"] == right["component"]
            and left["units"] == right["units"]
            and left["depends_on"] == right["depends_on"])


def read_retain(request):
    """Return the G2 rollback retain list as validated change IDs.

    `retain` defaults to an empty list. A malformed list is invalid-retain;
    whether its entries are actually applied is graph/replay knowledge and is
    checked by the planner as unknown-dependency.
    """
    retain = request.get("retain", [])
    if not isinstance(retain, list):
        _invalid("invalid-retain")
    for change_id in retain:
        if not isinstance(change_id, str) or not change_id:
            _invalid("invalid-retain")
    return retain


def read_applied(request):
    """Return the persisted release journal as a de-duplicated list of IDs."""
    applied = _read_ids(request.get("applied", []))
    unique = []
    seen = set()
    for change_id in applied:
        if change_id not in seen:
            seen.add(change_id)
            unique.append(change_id)
    return unique

