"""Compose policy and journal data into actions: graph, order and results."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, frozen, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(actions, units):
    return {"status": "ok", "actions": actions, "units": units}


class GraphError(ValueError):
    pass


def _topological_order(changes):
    """Kahn's algorithm, breaking ties by lexicographic ID among eligible nodes."""
    by_id = {change["id"]: change for change in changes}
    dependents = {change_id: [] for change_id in by_id}
    indegree = {}
    for change in changes:
        for dep in change["depends_on"]:
            if dep not in by_id:
                raise GraphError("unknown-dependency")
            dependents[dep].append(change["id"])
        indegree[change["id"]] = len(change["depends_on"])

    eligible = [change_id for change_id, degree in indegree.items() if degree == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        change_id = heapq.heappop(eligible)
        order.append(change_id)
        for child in dependents[change_id]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(eligible, child)
    if len(order) != len(by_id):
        raise GraphError("dependency-cycle")
    return order, by_id


def _retained_closure(by_id, retained):
    """The retained IDs plus the applied dependencies they transitively require."""
    keep = set(retained)
    stack = list(retained)
    while stack:
        for dep in by_id[stack.pop()]["depends_on"]:
            if dep not in keep:
                keep.add(dep)
                stack.append(dep)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    # G2: the freeze is decided before graph or change validation, so a frozen
    # request never reaches record parsing and never emits partial actions.
    if frozen(request):
        return failure("production-frozen")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        retained = read_retain(request) if request["action"] == "rollback" else []
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    try:
        order, by_id = _topological_order(changes)
    except GraphError as exc:
        return failure(str(exc))

    known = set(by_id)
    if any(change_id not in known for change_id in applied):
        return failure("unknown-dependency")
    applied_ids = [change_id for change_id in applied if change_id in known]

    if request["action"] == "plan":
        applied_set = set(applied_ids)
        pending = [change_id for change_id in order if change_id not in applied_set]
        units = sum(by_id[change_id]["units"] for change_id in pending)
        if units > budget:
            return failure("budget-exceeded")
        return success(pending, units)

    # rollback: only applied changes, in reverse of the full topological order.
    # G2: retained IDs and the applied dependencies they require are kept; the
    # budget was validated but does not cap a rollback.
    applied_set = set(applied_ids)
    if any(change_id not in applied_set for change_id in retained):
        return failure("unknown-dependency")
    keep = _retained_closure(by_id, set(retained))
    actions = [change_id for change_id in reversed(order)
               if change_id in applied_set and change_id not in keep]
    units = sum(by_id[change_id]["units"] for change_id in actions)
    return success(actions, units)

policy.py.text:
"""Validate release policy: environment, action and budget."""

ACTIONS = ("plan", "rollback")
ENVIRONMENTS = ("staging", "production")

# G2: this release ships to staging only; production plan and rollback are frozen.
FROZEN_ENVIRONMENTS = ("production",)

# G2: staging plans are additionally capped, whatever the request budget allows.
STAGING_PLAN_CAP = 3


class PolicyError(ValueError):
    pass


def frozen(request):
    """True when the requested environment is frozen before any other validation."""
    return request.get("environment") in FROZEN_ENVIRONMENTS


def limit_for(request):
    """Validate environment/action/budget and return the effective plan budget."""
    if request.get("environment") not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    if request["action"] == "plan":
        return min(budget, STAGING_PLAN_CAP)
    return budget

