journal.py.text:
"""Normalize release records at the input boundary.

This module owns the *identity* of a change: shape validation, the `depends_on` and
`applied` arrays, and replay de-duplication. It knows nothing about ordering, budget or
policy; those are composed in planner.py. Every rejection is raised as JournalError with
the SPEC error code as the message.
"""


class JournalError(ValueError):
    """Invalid change record, dependency list, applied journal, or duplicate ID."""


def _ids(value, code):
    """Return a frozenset of change IDs from a JSON array of nonempty strings.

    A missing value (None) is the documented default for both `depends_on` and
    `applied`, so it folds to the empty set here. Non-arrays and non-string members are
    rejected because a journal must be exactly what the caller persisted.
    """
    if value is None:
        return frozenset()
    if not isinstance(value, list):
        raise JournalError(code)
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError(code)
    return frozenset(value)


def _identity(row):
    """Return (component, units, dependency-set) for conflict comparison.

    Dependencies compare as a *set*: two records that list the same dependencies in a
    different order are the same change and must collapse, not conflict.
    """
    return (row["component"], row["units"], row["depends_on"])


def read_changes(records):
    """Validate and replay-deduplicate the `changes` array.

    Returns a list of {"id", "component", "units", "depends_on"}; `depends_on` is a
    plain list preserving the caller's order (the graph only needs membership).
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                # type(...) is int, not isinstance: bool subclasses int, and SPEC
                # excludes booleans from integers. `True` would pass `>= 1`.
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _ids(row.get("depends_on"), "invalid-change"),
        }
        prior = seen.get(change["id"])
        if prior is None:
            seen[change["id"]] = change
            changes.append(change)
        elif _identity(prior) != _identity(change):
            # Same ID, different content. Never "last write wins": replay must be
            # reproducible, and a silently dropped record would change the plan.
            raise JournalError("conflicting-change")
        # Else: identical duplicate, already collapsed.
    return changes


def read_applied(request):
    """Return the persisted release journal as a set of applied change IDs.

    `applied` is caller-supplied on every request; this module never reads a file.
    A missing value is the empty journal because SPEC defaults it.
    """
    return _ids(request.get("applied"), "invalid-change")

planner.py.text:
"""Compose policy and journal data into a plan.

Composition order is fixed by SPEC: policy first (so a refused action never reaches the
graph), then journal shape, then identity, then graph, cycle, and finally budget. Any
failure returns the canonical error object with no actions; nothing partial is emitted.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


class PlanningError(ValueError):
    """A graph or replay error discovered after policy and journal shape checks."""


def order_changes(changes):
    """Return the full deterministic topological order of every change ID.

    Kahn's algorithm with a min-heap on the *currently eligible* frontier. "Eligible" is
    the SPEC tie-break: among all changes whose dependencies are already emitted, the
    lexicographically smallest ID goes next. A depth-first order would emit a whole
    dependency chain before a lexicographically smaller sibling, so it must not be used.
    """
    ids = {change["id"] for change in changes}
    # Dependencies are validated against the full set, not against the subset that will
    # be emitted: an applied change can depend on an applied change, and both still have
    # to be real changes in this request for the journal to be coherent.
    for change in changes:
        for target in change["depends_on"]:
            if target not in ids:
                raise PlanningError("unknown-dependency")

    pending = {change["id"]: set(change["depends_on"]) for change in changes}
    dependents = {key: [] for key in pending}
    for change in changes:
        for target in change["depends_on"]:
            dependents[target].append(change["id"])
    ready = [key for key, deps in pending.items() if not deps]
    heapq.heapify(ready)

    order = []
    while ready:
        key = heapq.heappop(ready)
        order.append(key)
        for follower in dependents[key]:
            deps = pending[follower]
            deps.discard(key)
            if not deps:
                heapq.heappush(ready, follower)
    if len(order) != len(pending):
        # Anything left has a dependency never satisfied => it sits on (or below) a cycle.
        # Reported as a cycle, not as unknown-dependency: every target name is known here.
        raise PlanningError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        order = order_changes(changes)
    except (PolicyError, JournalError, PlanningError) as exc:
        return failure(str(exc))
    by_id = {change["id"]: change for change in changes}
    if applied - set(by_id):
        # An applied ID with no change record means the caller's journal and this request
        # disagree; planning on top of it would invent a release state.
        return failure("unknown-dependency")

    if action == "rollback":
        # Only applied changes, in the reverse of the *full* order. Filtering the full
        # order (rather than ordering the applied subset) keeps reverse order compatible
        # with dependencies: a reversed subset could try to undo a dependency first.
        actions = [key for key in reversed(order) if key in applied]
    else:
        # Already applied entries satisfy their dependents but are not re-emitted.
        actions = [key for key in order if key not in applied]
    units = sum(by_id[key]["units"] for key in actions)
    # Budget caps emitted units only, and only for plan. It is measured after replay and
    # de-duplication (collapse means duplicate records are not billed twice) and after
    # dropping applied entries (they cost nothing new). Rollback validates budget in
    # policy but is never capped by it.
    if action == "plan" and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

