"""JSON transport for the release planner.

Transport only: decode one JSON object from stdin, hand it to planner.plan, print exactly
one JSON object. Every outcome exits 0, including domain errors; a domain error is a
result, not a process failure. No files are written and no service is contacted.

UTF-8 is pinned on both ends on purpose. On Windows the default text encoding is the ANSI
code page, so without reconfigure() a non-ASCII change ID would print as escapes (clean)
or raise UnicodeEncodeError (replacement-unsafe locales) — the latter would be a
traceback and a non-zero exit, violating the "exit normally" contract.
"""
import json
import sys

from planner import plan


def main():
    # stdin first, output last: once stdout is UTF-8, a UTF-8 stdin must already be in place.
    # The stdio streams may carry no configurable encoding (e.g. a test harness replacement),
    # in which case leaving them alone is safer than raising.
    for stream in (sys.stdin, sys.stdout):
        try:
            stream.reconfigure(encoding="utf-8")
        except (AttributeError, ValueError, OSError):
            pass
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

