"""JSON transport for the release planner.

Transport only: read one request from stdin, hand it to planner, print one JSON
object, exit 0. This module deliberately does not know about environments,
budgets, dependencies or ordering -- those belong to policy and journal/planner.
Keeping it that way is what lets every domain rule be tested without stdin.

The stdin call runs before planning, so a non-JSON body is reported as
``invalid-json`` even if the rest of the wiring would fail for other reasons.
"""
import json
import sys

from planner import plan


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        # json.load raises ValueError (JSONDecodeError) for malformed text and
        # TypeError for non-text streams; both mean "this is not JSON".
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        try:
            result = plan(request)
        except Exception:
            # Last-resort containment: SPEC requires a JSON result on every
            # path and exit code 0, so an unexpected bug must not surface as a
            # traceback with no parseable output. It reuses an existing code
            # rather than inventing one, and emits no partial actions.
            result = {"status": "error", "error": "invalid-request", "actions": [], "units": 0}
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

