pilot-null-replay.py.text:
"""Replay the pilot review observation against the exact signed and repaired artifacts."""

from hashlib import sha256
import json
from pathlib import Path
import sys

from assess import execute


root = Path(__file__).resolve().parent
snapshot = root / "r-BkyqBE" / "assess" / "building-loop" / "g2"
versions = {"reviewed": "3165c2fac8ea0ef3368a", "repaired": "4580626dd75aac941a90"}
base = {"environment": "staging", "action": "rollback", "budget": 3,
        "changes": [{"id": "a", "component": "a", "units": 1}], "applied": ["a"]}
cases = {
    "explicit-null-retain": {**base, "retain": None},
    "absent-retain": base,
    "explicit-null-depends": {**base, "action": "plan",
        "changes": [{**base["changes"][0], "depends_on": None}]},
    "explicit-null-applied": {**base, "action": "plan", "applied": None},
    "plan-ignores-retain": {**base, "action": "plan", "retain": None},
}


def run():
    results = {}
    for label, name in versions.items():
        source = snapshot / name
        results[label] = {
            "sourcePins": {file.name: sha256(file.read_bytes()).hexdigest() for file in source.glob("*.py")},
            "cases": {key: execute(source, incoming) for key, incoming in cases.items()},
        }
    reviewed, repaired = (results[label]["cases"] for label in ("reviewed", "repaired"))
    assert reviewed["explicit-null-retain"][0]["status"] == "ok"
    assert repaired["explicit-null-retain"][0]["error"] == "invalid-retain"
    assert repaired["explicit-null-depends"][0]["error"] == repaired["explicit-null-applied"][0]["error"] == "invalid-change"
    for key in ("absent-retain", "plan-ignores-retain"):
        assert reviewed[key] == repaired[key] and repaired[key][0]["status"] == "ok"
    return {"method": "Independent WSL bubblewrap on exact pilot candidate snapshots",
            "interpretation": "SPEC declares depends_on and applied arrays, rejecting non-array dependencies or journal input. "
                "G2 does not spell out literal null, but describes retain as a list and rejects malformed lists; "
                "omitted fields still get the documented default and a plan ignores retain.",
            "inputs": cases, "versions": results}


if __name__ == "__main__":
    print(json.dumps(run(), indent=2))

